    "Galvenā vēlēšanās Gramzdas nākotnei": "Mana vēlēšanās Gramzdas nākotnei ir saglabāt tās mierīgo, sakopto un draudzīgo vidi, vienlaikus pakāpeniski attīstot jaunas iespējas iedzīvotājiem un viesiem. Vēlētos, lai Gramzda būtu vieta, kur cilvēki vēlas palikt, veidot ģimenes, strādāt un pavadīt brīvo laiku, kā arī vieta, kas ar savu dabu, kultūras dzīvi un sakārtoto vidi piesaista arvien vairāk apmeklētāju. Bet - PATI GALVENĀ VĒLĒŠANĀS - Lai vietējie iedzīvotāji (tie, kuri to vēl nespēj/nedara) sāk cienīt cits cita darbu, pūles un ieguldījumu mūsu ciematā - labiekārtošanas un visus citus darbus.. Sirds lūzt ik reizi, kad nākas redzēt salauztas, sabojātas lietas un ir sāpīgi apzināties, ka to dara mūsu pašu iedzīvotāji, kuriem vajadzētu priecāties par mūsu skaisto apkārtni nevis to bojāt."
